const key = (env.get("OPENWEATHER_API_KEY") || "").trim();
if (!key) {
    return [null, { payload: "Meteorología: falta OPENWEATHER_API_KEY" }];
}
const city = (env.get("OPENWEATHER_CITY") || "Vigo,ES").trim() || "Vigo,ES";
const url = "https://api.openweathermap.org/data/2.5/weather"
    + "?q=" + encodeURIComponent(city)
    + "&units=metric&lang=es&appid=" + encodeURIComponent(key);
return [{ url, requestTimeout: 10000 }, null];

const data = msg.payload;
if (msg.statusCode !== 200) {
    const hint = {
        401: "verifica la activación de la clave",
        404: "revisa OPENWEATHER_CITY",
        429: "límite de consultas alcanzado"
    }[msg.statusCode];
    return { payload: "Meteorología no disponible (HTTP " + msg.statusCode
        + (hint ? ": " + hint : "") + ")" };
}
if (!data || !Number.isFinite(data.main?.temp)
    || !Number.isFinite(data.main?.humidity) || !Number.isFinite(data.dt)
    || !data.name || !data.weather?.[0]?.description) {
    return { payload: "Meteorología: respuesta incompleta" };
}
const weather = {
    city: data.name,
    country: data.sys?.country,
    temperatureC: data.main.temp,
    humidityPct: data.main.humidity,
    description: data.weather[0].description,
    observedAt: new Date(data.dt * 1000).toISOString()
};
const time = new Intl.DateTimeFormat("es-ES", {
    timeZone: "Europe/Madrid", hour: "2-digit", minute: "2-digit",
    day: "2-digit", month: "2-digit"
}).format(new Date(weather.observedAt));
return {
    weather,
    payload: weather.city + " · " + weather.temperatureC.toFixed(1) + " °C · "
        + weather.humidityPct + " % HR · " + weather.description + " · " + time
};
